uint32_t dot4_sum(uint32_t rs1, uint32_t rs2) {
    int8_t a0 = (int8_t)(rs1 >> 0);
    int8_t a1 = (int8_t)(rs1 >> 8);
    int8_t a2 = (int8_t)(rs1 >> 16);
    int8_t a3 = (int8_t)(rs1 >> 24);
    int8_t b0 = (int8_t)(rs2 >> 0);
    int8_t b1 = (int8_t)(rs2 >> 8);
    int8_t b2 = (int8_t)(rs2 >> 16);
    int8_t b3 = (int8_t)(rs2 >> 24);
    return (uint32_t)((int32_t)a0*b0 + (int32_t)a1*b1 + (int32_t)a2*b2 + (int32_t)a3*b3);
}

uint32_t dot4_partials(uint32_t rs1, uint32_t rs2) {
    int8_t a0 = (int8_t)(rs1 >> 0);
    int8_t a1 = (int8_t)(rs1 >> 8);
    int8_t a2 = (int8_t)(rs1 >> 16);
    int8_t a3 = (int8_t)(rs1 >> 24);
    int8_t b0 = (int8_t)(rs2 >> 0);
    int8_t b1 = (int8_t)(rs2 >> 8);
    int8_t b2 = (int8_t)(rs2 >> 16);
    int8_t b3 = (int8_t)(rs2 >> 24);
    int16_t p0 = (int16_t)a0 * (int16_t)b0;
    int16_t p1 = (int16_t)a1 * (int16_t)b1;
    int16_t p2 = (int16_t)a2 * (int16_t)b2;
    int16_t p3 = (int16_t)a3 * (int16_t)b3;
    return (uint32_t)((uint16_t)p0 | ((uint32_t)(uint16_t)p1 << 16)) |
           ((uint32_t)(uint16_t)p2 << 0) | ((uint32_t)(uint16_t)p3 << 16); // actually pack as two 32-bit words? Wait, return is 32-bit. Can't return 4x16-bit. Must choose: return two 32-bit? No, single 32-bit return. So pack two 16-bit partials.
}

uint32_t hadd16(uint32_t rs1, uint32_t rs2) {
    (void)rs2; // unused, but signature requires two args
    int16_t lo = (int16_t)(rs1 & 0xFFFF);
    int16_t hi = (int16_t)(rs1 >> 16);
    return (uint32_t)(int32_t)(lo + hi);
}

uint32_t mula4_acc(uint32_t rs1, uint32_t rs2) {
    int8_t a0 = (int8_t)(rs1 >> 0);
    int8_t a1 = (int8_t)(rs1 >> 8);
    int8_t a2 = (int8_t)(rs1 >> 16);
    int8_t a3 = (int8_t)(rs1 >> 24);
    int8_t b0 = (int8_t)(rs2 >> 0);
    int8_t b1 = (int8_t)(rs2 >> 8);
    int8_t b2 = (int8_t)(rs2 >> 16);
    int8_t b3 = (int8_t)(rs2 >> 24);
    // Accumulator must come from somewhere. No third operand. So this instruction cannot accumulate into a running sum.
    // Constraint: f(rs1, rs2) only. No accumulator input. So mula4_acc impossible as described.
    // Must return just the 4 products sum. That's dot4_sum.
    // Alternative: rs1 holds 4 bytes, rs2 holds 4 bytes, return sum of products. That's dot4_sum.
    // So this proposal is duplicate. Need different idea.
    // Idea: 2-way int16 dot product (for requant or other). Or byte shuffle for packing.
    return 0;
}

uint32_t pack4x8(uint32_t rs1, uint32_t rs2) {
    // rs1: 4 bytes in low 32 bits (e.g., from 4 lb instructions)
    // rs2: 4 bytes in low 32 bits
    // But we need to pack 4 bytes from memory. Loads are separate.
    // This instruction can't load. It can only rearrange registers.
    // Use case: after 4 lb into 4 registers, pack them. But 4 lb -> 4 regs -> pack4x8(rs1,rs2) packs 2+2? 
    // Better: interleave bytes for dot4_sum? No.
    // Actually, software can load 4 bytes via lw if data is packed. If not, must use lb.
    // This instruction helps if data is not packed: load 4 bytes into 2 registers (2 lb each?), then pack.
    // But lb loads 1 byte. 4 lb = 4 regs. Need to combine 4 regs into 1. Requires 3 instructions (pack2, pack2, pack2).
    // Not efficient.
    // Alternative: sign-extend 4 int8 to 4 int16 in two 32-bit regs.
    return 0;
}

uint32_t dot2_16(uint32_t rs1, uint32_t rs2) {
    int16_t a0 = (int16_t)(rs1 & 0xFFFF);
    int16_t a1 = (int16_t)(rs1 >> 16);
    int16_t b0 = (int16_t)(rs2 & 0xFFFF);
    int16_t b1 = (int16_t)(rs2 >> 16);
    return (uint32_t)((int32_t)a0*b0 + (int32_t)a1*b1);
}

